  invalidValue: (p) => {
    switch (p.reason) {
      case "valueMissing":
        return "\u8BF7\u586B\u5199\u6B64\u5B57\u6BB5\u3002";
      case "typeMismatch":
        return p.type === "email" ? "\u8BF7\u8F93\u5165\u6709\u6548\u7684\u7535\u5B50\u90AE\u4EF6\u5730\u5740\u3002" : p.type === "url" ? "\u8BF7\u8F93\u5165\u6709\u6548\u7684\u7F51\u5740\u3002" : "\u8BF7\u8F93\u5165\u6709\u6548\u7684\u503C\u3002";
      case "badInput":
        return "\u8BF7\u8F93\u5165\u6570\u5B57\u3002";
      case "tooShort":
        return "\u81F3\u5C11 " + p.minLength + " \u4E2A\u5B57\u7B26\uFF08\u5F53\u524D " + p.length + " \u4E2A\uFF09\u3002";
      case "tooLong":
        return "\u6700\u591A " + p.maxLength + " \u4E2A\u5B57\u7B26\uFF08\u5F53\u524D " + p.length + " \u4E2A\uFF09\u3002";
      case "rangeUnderflow":
        return "\u503C\u5FC5\u987B\u5927\u4E8E\u6216\u7B49\u4E8E " + p.min + "\u3002";
      case "rangeOverflow":
        return "\u503C\u5FC5\u987B\u5C0F\u4E8E\u6216\u7B49\u4E8E " + p.max + "\u3002";
      case "stepMismatch":
        return "\u8BF7\u8F93\u5165 " + p.step + " \u7684\u500D\u6570\u3002";
      case "patternMismatch":
        return "\u8BF7\u6309\u8981\u6C42\u7684\u683C\u5F0F\u586B\u5199\u3002" + (p.title ? " " + p.title : "");
      default:
        return "";
    }
  },
